mapper.select:
SELECT p.id, p.circle_id, p.user_id, p.title, p.content, p.view_count, p.like_count, p.reply_count, p.status, p.created_time, pu.nickname AS author_name, pu.avatar AS author_avatar FROM portal_circle_post p LEFT JOIN portal_user pu ON pu.id = p.user_id
AND p.circle_id = #{circleId}
AND p.title LIKE CONCAT('%', #{keyword}, '%')
AND p.status = #{status}
ORDER BY p.created_time DESC
